<?php require_once __DIR__.'/../includes/auth.php';$a=require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($act==='delete'){$q=db()->prepare('DELETE FROM categories WHERE id=?');try{$q->execute([$id]);flash('success','Category deleted.');}catch(Throwable $e){flash('error','Category is in use and cannot be deleted.');}}else{$name=trim((string)($_POST['name']??''));$icon=trim((string)($_POST['icon']??'fa-tag'));if(text_length($name)>120||text_length($icon)>80||($icon!==''&&!preg_match('/^[a-z0-9-]+$/i',$icon))){flash('error','Category name or icon is invalid.');}elseif($name==='')flash('error','Category name is required.');else{if($id){$q=db()->prepare('UPDATE categories SET name=?,slug=?,icon=?,is_active=? WHERE id=?');$q->execute([$name,slugify($name),$icon,isset($_POST['is_active'])?1:0,$id]);}else{$q=db()->prepare('INSERT INTO categories(name,slug,icon,is_active) VALUES(?,?,?,1)');$q->execute([$name,slugify($name),$icon]);}log_activity((int)$a['id'],'category_saved','category',$id?:null,$name);flash('success','Category saved.');}}redirect('admin/categories.php');}$rows=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$pageTitle='Categories — Admin';require __DIR__.'/../includes/header.php';?><div class="container py-4"><?php include __DIR__.'/_nav.php';?><h1>Categories</h1><form method="post" class="card card-body shadow-sm border-0 mb-4"><?=csrf_field()?><div class="row g-2"><div class="col-md-5"><input class="form-control" name="name" placeholder="New category name" required></div><div class="col-md-4"><input class="form-control" name="icon" value="fa-tag" placeholder="Font Awesome icon"></div><div class="col-md-3"><button class="btn btn-primary w-100">Add category</button></div></div></form><div class="table-responsive"><table class="table"><tr><th>Name</th><th>Slug</th><th>Active</th><th>Delete</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['slug'])?></td><td><?=$r['is_active']?'Yes':'No'?></td><td><form method="post" data-confirm-submit="Delete this category?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="delete" class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>